import{_ as r,a0 as l,w as i,s as p,I as n,x as t,a1 as a,A as o,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"真的超赞！用systemd命令来管理linux系统！ | LCTT x X-CMD","titleTemplate":false,"description":"真的超赞！用systemd命令来管理linux系统！ | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"真的超赞！用systemd命令来管理linux系统！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"真的超赞！用systemd命令来管理linux系统！ | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140901 Awesome systemd Commands to Manage Linux System","title":"真的超赞！用systemd命令来管理linux系统！","tag":"201409","desc":""},"relativePath":"201409/20140901 Awesome systemd Commands to Manage Linux System.md","filePath":"[post].md"}'),m={name:"201409/20140901 Awesome systemd Commands to Manage Linux System.md"};function c(h,e,g,y,x,u){const s=l("Link");return i(),p("div",null,[e[18]||(e[18]=n("h1",{id:"真的超赞-用systemd命令来管理linux系统",tabindex:"-1"},[t("真的超赞！用systemd命令来管理linux系统！ "),n("a",{class:"header-anchor",href:"#真的超赞-用systemd命令来管理linux系统","aria-label":"Permalink to “真的超赞！用systemd命令来管理linux系统！”"},"​")],-1)),e[19]||(e[19]=n("p",null,"Systemd是一种新的linux系统服务管理器。",-1)),n("p",null,[e[2]||(e[2]=t("它替换了init系统，能够管理系统的启动过程和一些系统服务，一旦启动起来，就将监管整个系统。在本文中，我们用的是",-1)),a(s,{href:"http://linoxide.com/linux-how-to/install-systemd-centos-redhat/"},{default:o(()=>[...e[0]||(e[0]=[t("安装有 systemd 216 版本的centos 7.0",-1)])]),_:1}),e[3]||(e[3]=t("，其最新版本",-1)),a(s,{href:"http://www.freedesktop.org/software/systemd/"},{default:o(()=>[...e[1]||(e[1]=[t("可以从 freedesktop.org 下载得到",-1)])]),_:1}),e[4]||(e[4]=t("。",-1))]),e[20]||(e[20]=d(`<p>因为linux操作系统里出现的这一个新人，PID 1被“systemd”占据了，这能通过<strong>pstree</strong>命令看到。</p><pre><code>[root@linoxide ~]# pstree
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/01.systemd_pstree.png" alt=""></p><p>那么现在让我们来探索systemd擅长什么，它又有多大的可能性成为sysVinit的新的替代品。</p><h3 id="_1-更快启动" tabindex="-1">1. 更快启动 <a class="header-anchor" href="#_1-更快启动" aria-label="Permalink to “1. 更快启动”">​</a></h3><p>sysvinit一次一个串行地启动进程。</p><p>而Systemd则并行地启动系统服务进程，并且最初仅启动确实被依赖的那些服务，极大地减少了系统引导的时间。</p><p>你可以用下面的命令看到系统引导用时：</p><pre><code>[root@linoxide ~]# systemd-analyze
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/02.systemd_analyze.png" alt=""></p><p>使用 <strong>time</strong> 参数也能够显示同样的内容。</p><pre><code>[root@linoxide ~]# systemd-analyze time
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/03.systemd_analyze2.png" alt=""></p><p>如果你想以进程初始化所占用时间排序打印出所有正在运行的单元列表，那么<strong>systemd-analyze</strong>命令可以帮助你完成这个任务。</p><pre><code>[root@linoxide ~]# systemd-analyze blame
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/04.systemd_blame.png" alt=""></p><p>上面的截屏只显示了小部分进程，你可以就像less分页器那样用箭头滚动列表。</p><h3 id="_2-systemctl-命令" tabindex="-1">2. systemctl 命令 <a class="header-anchor" href="#_2-systemctl-命令" aria-label="Permalink to “2.  systemctl 命令”">​</a></h3><p>systemctl命令是自systemd出现以来被广泛讨论的命令。你可以通过这个命令管理你的整个系统，让我们通过探究这个命令来更进一步。</p><h4 id="_2-1-列出单元" tabindex="-1">2.1 列出单元 <a class="header-anchor" href="#_2-1-列出单元" aria-label="Permalink to “2.1 列出单元”">​</a></h4><p><strong>systemctl</strong>命令可以带上list-units，也可以什么选项都不带来列出所有正在运行的单元。</p><pre><code>[root@linoxide ~]# systemctl
</code></pre><p>或</p><pre><code>[root@linoxide ~]# systemctl list-units
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/05.systemd_list_units.png" alt=""></p><h4 id="_2-2-列出失败的单元" tabindex="-1">2.2 列出失败的单元 <a class="header-anchor" href="#_2-2-列出失败的单元" aria-label="Permalink to “2.2 列出失败的单元”">​</a></h4><p>运行失败的单元可以用带--failed选项的命令显示出来。</p><pre><code>[root@linoxide ~]# systemctl --failed
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/06.systemd_failed.png" alt=""></p><p>你可以在这篇文章很多地方看到systemctl的用法。</p><h3 id="_3-管理服务" tabindex="-1">3. 管理服务 <a class="header-anchor" href="#_3-管理服务" aria-label="Permalink to “3. 管理服务”">​</a></h3><p>让我们来看看systemd是怎么管理系统服务的。</p><h4 id="_3-1-激活的服务" tabindex="-1">3.1 激活的服务 <a class="header-anchor" href="#_3-1-激活的服务" aria-label="Permalink to “3.1 激活的服务”">​</a></h4><p>所有被激活的服务可以同下面这条命令来查看。</p><pre><code>[root@linoxide ~]# systemctl list-units -t service
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/07.systemd_active_services.png" alt=""></p><h4 id="_3-2-服务状态" tabindex="-1">3.2 服务状态 <a class="header-anchor" href="#_3-2-服务状态" aria-label="Permalink to “3.2 服务状态”">​</a></h4><p>在sysvinit中，我们可以用“<strong>service</strong>”命令来管理服务，但在systemd中，我们用systemctl这个命令。 我们可以用下面这个命令来查看服务是否在运行。</p><pre><code>[root@linoxide ~]# systemctl status dnsmasq
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/08.systemd_status.png" alt=""></p><h4 id="_3-3-启动一个服务" tabindex="-1">3.3 启动一个服务 <a class="header-anchor" href="#_3-3-启动一个服务" aria-label="Permalink to “3.3 启动一个服务”">​</a></h4><p>用下面这条命令来启动服务。</p><pre><code>[root@linoxide ~]# systemctl start dnsmasq
</code></pre><p>对应于<strong>service</strong>命令，这个命令不进行输出。但是毋庸置疑，我们可以通过再次查看这个刚刚被启动的服务的status（状态）来确认他是否被成功地启动了。</p><p><img src="http://linoxide.com/wp-content/uploads/2014/08/09.systemd_start.png" alt=""></p><h4 id="_3-4-停止一个服务" tabindex="-1">3.4 停止一个服务 <a class="header-anchor" href="#_3-4-停止一个服务" aria-label="Permalink to “3.4 停止一个服务”">​</a></h4><p>现在聪明的你一定知道怎么在systemd下用命令来关闭服务了吧。</p><pre><code>[root@linoxide ~]# systemctl stop dnsmasq
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/10.systemd_stop.png" alt=""></p><h4 id="_3-5-重启一个服务" tabindex="-1">3.5 重启一个服务 <a class="header-anchor" href="#_3-5-重启一个服务" aria-label="Permalink to “3.5 重启一个服务”">​</a></h4><p>类似的，重启系统服务是用‘<strong>systemctl restart</strong>’来管理的。</p><pre><code>[root@linoxide ~]# systemctl restart dnsmasq
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/11.systemd_restart.png" alt=""></p><h4 id="_3-6-重新加载一个服务" tabindex="-1">3.6 重新加载一个服务 <a class="header-anchor" href="#_3-6-重新加载一个服务" aria-label="Permalink to “3.6 重新加载一个服务”">​</a></h4><p>在我们需要重新加载服务的配置文件又不想重启这个服务（例如ssh）时，我们可以用这个命令。</p><pre><code>[root@linoxide ~]# systemctl reload sshd
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/12.systemd_reload.png" alt=""></p><p>虽然上述几个命令的语法是可以工作的，但是官方文档建议我们用下面这种语法形式来运行命令（LCTT 译注，即使用在服务名后面跟上“.service”的完整名称）：</p><pre><code>[root@linoxide ~]# systemctl status dnsmasq.service
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/13.systemd_alternate_syntax.png" alt=""></p><h3 id="_4-管理引导时的服务" tabindex="-1">4. 管理引导时的服务 <a class="header-anchor" href="#_4-管理引导时的服务" aria-label="Permalink to “4. 管理引导时的服务”">​</a></h3><p><strong>chkconfig</strong>命令被用来管理系统引导时的服务。同样用systemd也可以管理引导时的系统服务。</p><h4 id="_4-1-检查服务引导时是否运行" tabindex="-1">4.1 检查服务引导时是否运行 <a class="header-anchor" href="#_4-1-检查服务引导时是否运行" aria-label="Permalink to “4.1 检查服务引导时是否运行”">​</a></h4><p>这条命令用来确定服务是否是引导时启动的。</p><pre><code>[root@linoxide ~]# systemctl is-enabled dnsmasq.service
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/14.systemd_is_enabled.png" alt=""></p><h4 id="_4-2-让服务在引导时运行" tabindex="-1">4.2 让服务在引导时运行 <a class="header-anchor" href="#_4-2-让服务在引导时运行" aria-label="Permalink to “4.2 让服务在引导时运行”">​</a></h4><p><strong>systemctl</strong>命令是这样来enable（使之在引导时启动）一个服务的。（这相当于sysvinit中的‘<strong>chkconfig on</strong>’）</p><pre><code>[root@linoxide ~]# systemctl enable dnsmasq.service
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/15.systemd_enable.png" alt=""></p><h4 id="_4-3-取消服务在引导时运行" tabindex="-1">4.3 取消服务在引导时运行 <a class="header-anchor" href="#_4-3-取消服务在引导时运行" aria-label="Permalink to “4.3 取消服务在引导时运行”">​</a></h4><p>类似的，使服务不在引导时启动用这个命令。</p><pre><code>[root@linoxide ~]# systemctl disable dnsmasq.service
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/16.systemd_disable.png" alt=""></p><h3 id="_5-管理远程系统" tabindex="-1">5. 管理远程系统 <a class="header-anchor" href="#_5-管理远程系统" aria-label="Permalink to “5. 管理远程系统”">​</a></h3><p>所有刚才提到的systemctl命令通常都能被用来管理远程主机，完成这个任务将用到<strong>ssh</strong>来进行通讯。你只需要像这样将远程主机和用户名添加到systemctl命令后。</p><pre><code>[root@linoxide ~]# systemctl status sshd -H root@1.2.3.4
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/17.systemd_remote.png" alt=""></p><h3 id="_6-管理目标" tabindex="-1">6. 管理目标 <a class="header-anchor" href="#_6-管理目标" aria-label="Permalink to “6. 管理目标”">​</a></h3><p>Systemd有一个完成与sysVinit的runlevels相似任务的构想。</p><p>sysVinit的runlevels大多是以数字分级的。这里是runlevers在systemd中的对应元素。</p><blockquote><p>0 runlevel0.target, poweroff.target</p><p>1, s, single runlevel1.target, rescue.target</p><p>2, 4 runlevel2.target, runlevel4.target, multi-user.target</p><p>3 runlevel3.target, multi-user.target</p><p>5 runlevel5.target, graphical.target</p><p>6 runlevel6.target, reboot.target</p><p>emergency emergency.target</p></blockquote><h4 id="_6-1-改变当前目标" tabindex="-1">6.1 改变当前目标 <a class="header-anchor" href="#_6-1-改变当前目标" aria-label="Permalink to “6.1 改变当前目标”">​</a></h4><p>当前target可以用这个命令切换。</p><pre><code>[root@linoxide ~]# systemctl isolate graphical.target
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/18.systemd_isolate.png" alt=""></p><h4 id="_6-2-列出当前目标" tabindex="-1">6.2 列出当前目标 <a class="header-anchor" href="#_6-2-列出当前目标" aria-label="Permalink to “6.2 列出当前目标”">​</a></h4><p>如果你想查看你正处于哪个target中，你需要列出相应的单元。虽然这样操作可能让你不太爽，但是这就是systemd工作的方式。</p><pre><code>[root@linoxide ~]# systemctl list-units --type=target
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/19.systemd_targets.png" alt=""></p><p>你可以看到“graphical.target”列在此处，这就是我们刚才切换到的目标。现在，让我们切换runlevel到multi-user.target，然后分析下列命令的输出。</p><pre><code>[root@linoxide ~]# systemctl isolate multi-user.target
[root@linoxide ~]# systemctl list-units --type=target
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/20.systemd_multi-user.png" alt=""></p><h4 id="_6-3-列出默认目标" tabindex="-1">6.3 列出默认目标 <a class="header-anchor" href="#_6-3-列出默认目标" aria-label="Permalink to “6.3 列出默认目标”">​</a></h4><p>用这个systemctl命令来查看默认目标。</p><pre><code>[root@linoxide ~]# systemctl get-default
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/21.systemd_get_default.png" alt=""></p><h4 id="_6-4-改变默认目标" tabindex="-1">6.4 改变默认目标 <a class="header-anchor" href="#_6-4-改变默认目标" aria-label="Permalink to “6.4 改变默认目标”">​</a></h4><p>通过systemctl的set-default命令可以将某个目标设置成默认目标。</p><pre><code>[root@linoxide ~]# systemctl set-default graphical.target
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/22.systemd_set_default.png" alt=""></p><h3 id="_7-记录-systemd-的日志" tabindex="-1">7. 记录 systemd 的日志 <a class="header-anchor" href="#_7-记录-systemd-的日志" aria-label="Permalink to “7. 记录 systemd 的日志”">​</a></h3><p>journald是systemd独有的日志系统，替换了sysVinit中的syslog守护进程。命令<strong>journalctl</strong>用来读取日志。</p><pre><code>[root@linoxide ~]# journalctl
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/23.systemd_logs.png" alt=""></p><h4 id="_7-1-查看引导信息" tabindex="-1">7.1 查看引导信息 <a class="header-anchor" href="#_7-1-查看引导信息" aria-label="Permalink to “7.1 查看引导信息”">​</a></h4><p>运行<strong>journalctl -b</strong>命令来查看所有引导日志。</p><pre><code>[root@linoxide ~]# journalctl -b
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/24.systemd_boot.png" alt=""></p><h4 id="_7-2-即时显示引导日志" tabindex="-1">7.2 即时显示引导日志 <a class="header-anchor" href="#_7-2-即时显示引导日志" aria-label="Permalink to “7.2 即时显示引导日志”">​</a></h4><p>下面这个命令可以实时显示系统日志（类似<strong>tail -f</strong>）。</p><pre><code>[root@linoxide ~]# journalctl -f
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/25.systemd_follow_logs.png" alt=""></p><h4 id="_7-3-查看特定服务的日志" tabindex="-1">7.3 查看特定服务的日志 <a class="header-anchor" href="#_7-3-查看特定服务的日志" aria-label="Permalink to “7.3 查看特定服务的日志”">​</a></h4><p>你可以像这样运用<strong>journalctl</strong>来查看你只想看到的服务或可执行程序的日志。</p><pre><code>[root@linoxide ~]# journalctl /usr/sbin/dnsmasq
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/26.systemd_specific.png" alt=""></p><h3 id="_8-电源管理" tabindex="-1">8. 电源管理 <a class="header-anchor" href="#_8-电源管理" aria-label="Permalink to “8. 电源管理”">​</a></h3><p>systemctl命令也可以用来关机，重启或者休眠。</p><p>要关机、重启、挂起和休眠，分别使用如下命令：</p><pre><code>[root@linoxide ~]# systemctl poweroff

[root@linoxide ~]# systemctl reboot

[root@linoxide ~]# systemctl suspend

[root@linoxide ~]# systemctl hibernate
</code></pre><h3 id="_9-又及" tabindex="-1">9. 又及 <a class="header-anchor" href="#_9-又及" aria-label="Permalink to “9. 又及”">​</a></h3><p><strong>systemd</strong>带来了一整套与操作系统交互的新途径，并且极具特色。举个栗子，你可以用hostnamectl命令来获得你的linux机器的hostname和其它有用的独特信息。</p><pre><code>[root@linoxide ~]# hostnamectl
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2014/08/27.systemd_hostnamectl.png" alt=""></p><hr>`,126)),n("p",null,[e[6]||(e[6]=t("via: ",-1)),a(s,{href:"http://linoxide.com/linux-command/linux-systemd-commands/"},{default:o(()=>[...e[5]||(e[5]=[t("http://linoxide.com/linux-command/linux-systemd-commands/",-1)])]),_:1})]),n("p",null,[e[10]||(e[10]=t("作者：",-1)),a(s,{href:"http://linoxide.com/author/raghu/"},{default:o(()=>[...e[7]||(e[7]=[t("Raghu",-1)])]),_:1}),e[11]||(e[11]=t(" 译者：",-1)),a(s,{href:"https://github.com/szrlee"},{default:o(()=>[...e[8]||(e[8]=[t("szrlee",-1)])]),_:1}),e[12]||(e[12]=t(" 校对：",-1)),a(s,{href:"https://github.com/wxy"},{default:o(()=>[...e[9]||(e[9]=[t(" wxy",-1)])]),_:1})]),n("p",null,[e[15]||(e[15]=t("本文由 ",-1)),a(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[13]||(e[13]=[t("LCTT",-1)])]),_:1}),e[16]||(e[16]=t(" 原创翻译，",-1)),a(s,{href:"http://linux.cn/"},{default:o(()=>[...e[14]||(e[14]=[t("Linux中国",-1)])]),_:1}),e[17]||(e[17]=t(" 荣誉推出",-1))])])}const w=r(m,[["render",c]]);export{f as __pageData,w as default};
